\set ON_ERROR_STOP on
CREATE FUNCTION public._fail(label text,s text)RETURNS void LANGUAGE plpgsql AS $$BEGIN EXECUTE s;RAISE EXCEPTION 'MISSED %',label;EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE'MISSED %'THEN RAISE;END IF;RAISE NOTICE 'expected [%]: %',label,SQLERRM;END$$;GRANT EXECUTE ON FUNCTION public._fail(text,text)TO service_role;
INSERT INTO public.mastermind_portal_resources(id,portal_resource_id,title,approved_access_scope,available_until)VALUES('10000000-0000-0000-0000-000000000001','r1','Resource','mastermind_lifetime','2099-01-01'),('10000000-0000-0000-0000-000000000002','r2','Duplicate','mastermind_lifetime','2099-01-01'),('10000000-0000-0000-0000-000000000003','r3','Private','mastermind_lifetime','2099-01-01');
DO $$BEGIN IF has_table_privilege('service_role','public.replay_publication_authority','INSERT')OR has_table_privilege('anon','public.replay_publication_authority','SELECT')OR has_table_privilege('authenticated','public.replay_published_resource_projection','SELECT')OR EXISTS(SELECT 1 FROM pg_proc p, LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner)))x WHERE p.oid='public.replay_import_content_package(jsonb,text)'::regprocedure AND x.grantee=0 AND x.privilege_type='EXECUTE')OR has_function_privilege('anon','public.replay_publish_resource(uuid,text)','EXECUTE')OR NOT has_function_privilege('service_role','public.replay_publish_resource(uuid,text)','EXECUTE')THEN RAISE EXCEPTION'ACL';END IF;IF EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public'AND p.proname IN('replay_import_content_package','replay_mark_resource_ready','replay_approve_resource','replay_publish_resource','replay_revoke_resource')AND(NOT p.prosecdef OR NOT p.proconfig@>ARRAY['search_path=pg_catalog, public']))THEN RAISE EXCEPTION'definer path';END IF;END$$;
SET ROLE service_role;
SELECT public._fail('direct insert',$q$INSERT INTO public.replay_publication_authority(resource_id,state,run_id,package_sha256,transcript_source_asset_id,media_source_asset_id,transcript_version_id,playback_attempt_id,pairing_candidate_id,transcript_content_sha256,media_evidence_sha256,source_identity_sha256)VALUES(gen_random_uuid(),'PUBLISHED',gen_random_uuid(),repeat('a',64),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),repeat('b',64),repeat('c',64),repeat('d',64))$q$);
