RESET ROLE;DO $$BEGIN IF(SELECT count(*)FROM public.replay_transcript_versions WHERE resource_id='10000000-0000-0000-0000-000000000001'AND is_active)<>1 OR EXISTS(SELECT 1 FROM public.replay_publication_authority a JOIN public.replay_transcript_segments s ON s.transcript_version_id=a.transcript_version_id WHERE a.resource_id='10000000-0000-0000-0000-000000000001'AND s.transcript_text_private='STALE_TAIL')THEN RAISE EXCEPTION'stale tail';END IF;END$$;
