RESET ROLE;UPDATE public.replay_publication_controls SET publication_enabled=true,changed_by='fixture';SET ROLE service_role;SELECT public.replay_publish_resource('10000000-0000-0000-0000-000000000001','publisher');
DO $$BEGIN IF(SELECT count(*)FROM public.replay_published_resource_projection)<>1 THEN RAISE EXCEPTION'publish';END IF;END$$;RESET ROLE;
DO $$DECLARE c uuid;q uuid;a public.replay_publication_authority%ROWTYPE;i int;BEGIN SELECT*INTO a FROM public.replay_publication_authority WHERE resource_id='10000000-0000-0000-0000-000000000001';FOR i IN 1..3 LOOP INSERT INTO public.replay_question_clusters(normalized_question_member_safe,editorial_status)VALUES('q'||i,'approved')RETURNING id INTO c;INSERT INTO public.replay_question_candidates(resource_id,transcript_version_id,question_segment_index,question_start_ms,answer_start_ms,answer_end_ms,raw_excerpt_private,raw_excerpt_sha256,extractor_version,proposed_question_private,source_privacy_flag,state,origin,content_sha256)VALUES(a.resource_id,a.transcript_version_id,i,0,0,1000,CASE WHEN i=3 THEN'PRIVATE_SENTINEL'ELSE'safe'END,repeat('a',64),'fixture','q'||i,CASE WHEN i=2 THEN'do_not_use'ELSE'clear'END,'approved',CASE WHEN i=1 THEN'generated'ELSE'human_curated'END,repeat('b',64))RETURNING id INTO q;INSERT INTO public.replay_answers(question_cluster_id,question_candidate_id,resource_id,transcript_version_id,playback_attempt_id,question_start_ms,answer_start_ms,answer_end_ms,member_question,safe_answer_summary,answerer_attribution,visibility_scope,privacy_approval,editorial_approval,seek_approval,privacy_reviewer,editorial_reviewer,seek_reviewer,privacy_reviewed_at,editorial_reviewed_at,seek_reviewed_at,published_at,publication_state,content_sha256)VALUES(c,q,a.resource_id,a.transcript_version_id,a.playback_attempt_id,0,0,1000,'q','safe','coach','members','approved','approved','approved','p','e','s',now(),now(),now(),now(),'PUBLISHED',repeat('c',64));END LOOP;END$$;
SET ROLE service_role;DO $$BEGIN IF(SELECT count(*)FROM public.replay_published_answers_projection)<>0 THEN RAISE EXCEPTION'unsafe question';END IF;END$$;SELECT public.replay_revoke_resource('10000000-0000-0000-0000-000000000001','revoker','withdrawn');RESET ROLE;DO $$BEGIN IF EXISTS(SELECT 1 FROM public.replay_published_resource_projection)OR NOT EXISTS(SELECT 1 FROM public.replay_publication_authority WHERE resource_id='10000000-0000-0000-0000-000000000001'AND state='REVOKED'AND published_at IS NOT NULL AND revoked_at IS NOT NULL)THEN RAISE EXCEPTION'revoke';END IF;END$$;RESET ROLE;
